import '@servicenow/sdk/global'
import { action, FlowArray, FlowObject, Subflow, wfa } from '@servicenow/sdk/automation'
import {
    BooleanColumn,
    DateTimeColumn,
    DecimalColumn,
    FloatColumn,
    GenericColumn,
    IntegerColumn,
    JsonColumn,
    ReferenceColumn,
    StringColumn,
} from '@servicenow/sdk/core'

export const logUserNameSubflow = Subflow(
    {
        $id: Now.ID['log_user_name_test_subflow'],
        name: 'Log user name test subflow',
        runAs: 'user',
        inputs: {
            user_name: StringColumn({
                label: 'User Name',
                maxLength: 8000,
            }),
        },
        outputs: {
            successful: BooleanColumn({
                label: 'Successful',
            }),
            empDetails: ReferenceColumn({
                mandatory: true,
                label: 'Employee Details',
                referenceTable: 'sys_user',
            }),
        },
    },
    (params) => {
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['test_subflow_outputs'],
                annotation: 'Test Subflow Outputs',
            },
            params.outputs,
            { successful: true }
        )

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_user_name_test_subflow_step1'],
                annotation: 'Log user name',
            },
            {
                log_level: 'info',
                log_message: `User name = ${params}`,
            }
        )
    }
)

