/**
 * Example: Subflow with Complex Object Types
 * Demonstrates: FlowObject inputs and outputs with assignSubflowOutputs
 * Shows how to use direct values (literals), object literals, and datapills with complex types
 */
Subflow(
    {
        $id: Now.ID['sub_1'],
        name: 'Subflow with Complex object',
        description: 'Demonstrates FlowObject types with assignSubflowOutputs',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
        inputs: {
            someString: StringColumn({ label: 'someString' }),
            someObject: FlowObject({
                fields: {
                    a: StringColumn({ label: 'a', mandatory: false }),
                    b: StringColumn({
                        label: 'b',
                        mandatory: false,
                    }),
                },
                label: 'someObject',
                mandatory: false,
            }),
        },
        outputs: {
            resultString: StringColumn({ label: 'Result String', mandatory: true }),
            inputEcho: StringColumn({ label: 'Input Echo', mandatory: true }),
            objOutput: FlowObject({
                fields: {
                    outputA: StringColumn({ label: 'outputA', mandatory: false }),
                    outputB: StringColumn({
                        label: 'outputB',
                        mandatory: false,
                    }),
                },
                label: 'objOutput',
                mandatory: false,
            }),
        },
    },
    (params) => {
        // Demonstrates all supported data types for complex objects
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign_complex_outputs'],
                annotation: 'Assign outputs with complex types',
            },
            params.outputs,
            {
                resultString: 'Processed successfully', //  String literal (direct value)
                inputEcho: wfa.dataPill(params.inputs.someString, 'string'), //  Datapill (PropertyAccessShape)
            }
        )
    }
)

/**
 * Example: Multi-Level Complex Object with Nested Datapills
 * Demonstrates: Deeply nested FlowObject types and accessing nested properties via datapills
 * Shows PropertyAccessShape for complex nested structures
 */
export const multiLevelComplexObjectSubflow = Subflow(
    {
        $id: Now.ID['subflow_00'],
        name: 'Subflow with Multi-Level Complex Objects',
        description: 'Demonstrates nested FlowObject access via datapills',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
        inputs: {
            test1: BooleanColumn({ mandatory: false, label: 'test1' }),
            cmpx: FlowObject({
                fields: {
                    level0_string: StringColumn({
                        label: 'level0_string',
                    }),
                    level0_object: FlowObject({
                        fields: {
                            level1_string: StringColumn({
                                label: 'level1_string',
                            }),
                            level1_object: FlowObject({
                                fields: {
                                    level2_string: StringColumn({
                                        label: 'level2_string',
                                    }),
                                    level2_object: FlowObject({
                                        fields: {
                                            level3_string: StringColumn({
                                                label: 'level3_string',
                                            }),
                                        },
                                        label: '',
                                        mandatory: false,
                                    }),
                                },
                                label: '',
                                mandatory: false,
                            }),
                        },
                        label: '',
                        mandatory: false,
                    }),
                },
                label: 'cmpx',
                mandatory: false,
            }),
        },
        outputs: {
            test: StringColumn({
                label: 'test',
                mandatory: true,
            }),
            level0Data: StringColumn({
                label: 'Level 0 Data',
                mandatory: true,
            }),
            level1Data: StringColumn({
                label: 'Level 1 Data',
                mandatory: true,
            }),
            deeplyNestedData: StringColumn({
                label: 'Deeply Nested Data',
                mandatory: true,
            }),
            cmpxOutput: FlowObject({
                fields: {
                    test2: StringColumn({
                        label: 'test2',
                    }),
                    nestedIp: FlowObject({
                        fields: {
                            nestedTest: StringColumn({
                                label: 'nestedTest',
                            }),
                        },
                        label: '',
                        mandatory: false,
                    }),
                },
                label: 'cmpxOutput',
                mandatory: false,
            }),
        },
    },
    (params) => {
        // wfa.subflow(
        //     subflowWithComplexInput,
        //     { $id: Now.ID['subflow_with_body'], annotation: 'Process complex input data' },
        //     {
        //         someString: 'Some input',
        //         someObject: { a: 'hello', b: 'world' },
        //     }
        // )

        //  Demonstrates accessing deeply nested FlowObject properties via datapills
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign_multilevel_outputs'],
                annotation: 'Assign outputs from nested complex objects',
            },
            params.outputs,
            {
                test: 'Completed', //  String literal
                //  PropertyAccessShape accessing nested FlowObject properties at different levels
                level0Data: wfa.dataPill(params.inputs.cmpx.level0_string, 'string'), // Level 0 property
                level1Data: wfa.dataPill(params.inputs.cmpx.level0_object.level1_string, 'string'), // Level 1 property
                deeplyNestedData: wfa.dataPill(params.inputs.cmpx.level0_object.level1_object.level2_string, 'string'), // Level 2 property
                // Can also use datapills from subflow results (identifiers)
            }
        )
    }
)

/**
 * Example: Subflow with Flow Variables and All Data Types
 * Demonstrates: setFlowVariables with all supported data types including:
 * - Primitive types (string, number, boolean, decimal)
 * - Special column types (DateTime, Reference, Generic)
 * - Complex types (FlowObject, FlowArray)
 * - Using direct values (literals), object/array literals, datapills, and template expressions
 * NOTE: Local variable references (IdentifierShape) are NOT supported - use direct values or datapills only
 */
export const subflowWithFlowVariables = Subflow(
    {
        $id: Now.ID['subflow_flow_variables'],
        name: 'Subflow with Flow Variables - All Data Types',
        description: 'Demonstrates setFlowVariables with all supported data types',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
        inputs: {
            test1: BooleanColumn({ mandatory: false, label: 'test1' }),
            inputRef: ReferenceColumn({ label: 'Input Reference', referenceTable: 'incident' }),
            cmpx: FlowObject({
                fields: {
                    level0_string: StringColumn({
                        label: 'level0_string',
                    }),
                    level0_object: FlowObject({
                        fields: {
                            level1_string: StringColumn({
                                label: 'level1_string',
                            }),
                            level1_object: FlowObject({
                                fields: {
                                    level2_string: StringColumn({
                                        label: 'level2_string',
                                    }),
                                    level2_object: FlowObject({
                                        fields: {
                                            level3_string: StringColumn({
                                                label: 'level3_string',
                                            }),
                                        },
                                        label: '',
                                        mandatory: false,
                                    }),
                                },
                                label: '',
                                mandatory: false,
                            }),
                        },
                        label: '',
                        mandatory: false,
                    }),
                },
                label: 'cmpx',
                mandatory: false,
            }),
        },
        outputs: {
            test: StringColumn({
                label: 'test',
            }),
            cmpxOutput: FlowObject({
                fields: {
                    test2: StringColumn({
                        label: 'test2',
                    }),
                    nestedIp: FlowObject({
                        fields: {
                            nestedTest: StringColumn({
                                label: 'nestedTest',
                            }),
                        },
                        label: '',
                        mandatory: false,
                    }),
                },
                label: 'cmpxOutput',
                mandatory: false,
            }),
        },
        flowVariables: {
            // Primitive types
            totalCount: IntegerColumn({
                maxLength: 10,
                mandatory: true,
                label: 'Total Processed',
            }),
            active: BooleanColumn({
                mandatory: true,
                label: 'Active',
            }),
            variable3: StringColumn({
                label: 'variable3',
                maxLength: 65000,
            }),
            variable1: DecimalColumn({
                label: 'variable1',
                maxLength: 65000,
            }),
            // Special column types
            quick_start_config: GenericColumn({
                mandatory: false,
                label: 'Quick start config',
                columnType: 'float',
            }),
            nativeFloatVar: FloatColumn({
                mandatory: false,
                label: 'Native Float Variable',
                scale: 2,
            }),
            jsonConfigVar: JsonColumn({
                mandatory: false,
                label: 'JSON Configuration Variable',
            }),
            variable2: DateTimeColumn({
                label: 'variable2',
                maxLength: 65000,
            }),
            reference: ReferenceColumn({
                label: 'reference',
                referenceTable: 'incident',
            }),
            // Complex types (Note: Values would be assigned via datapills)
            check: FlowObject({
                fields: {
                    name: StringColumn({
                        mandatory: true,
                        label: 'Name',
                    }),
                },
                mandatory: true,
                label: 'Active',
            }),
            processIds: FlowArray({
                mandatory: true,
                label: 'Process IDs',
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({
                            mandatory: true,
                            label: 'Name',
                        }),
                    },
                    mandatory: true,
                    label: 'Active',
                }),
                childName: 'processIds',
            }),
        },
    },
    (params) => {
        //  Demonstrates setFlowVariables with ALL supported data types
        // Note: This example shows the schema definition. When setFlowVariables is fully enabled,
        // you would assign values like this:
        /*
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_all_flow_vars'],
                annotation: 'Set flow variables demonstrating all data types',
            },
            params.flowVariables,
            {
                //  Primitive types with direct literals
                totalCount: 250,                         //  IntegerColumn with number literal
                active: true,                            //  BooleanColumn with boolean literal
                variable1: 99.99,                        //  DecimalColumn with number literal
                variable3: 'Processed successfully',     //  StringColumn with string literal

                //  Special column types
                quick_start_config: 3.14159,             //  GenericColumn with number literal
                nativeFloatVar: 456.78,                  //  FloatColumn with number literal
                jsonConfigVar: '{"enabled": true, "timeout": 30}', //  JsonColumn with JSON string literal
                reference: params.inputs.inputRef,       //  ReferenceColumn with PropertyAccessShape (datapill)

                //  Template expressions (datapills only, no local variables)
                variable2: `Current time: ${params.inputs.test1}`, //  DateTimeColumn with template using datapill

                //  Complex types - can use object/array literals or datapills
                check: { name: 'Process Complete' },     //  FlowObject with ObjectShape (object literal)
                processIds: [                            //  FlowArray with ArrayShape (array literal)
                    { name: 'Process 1' },
                    { name: 'Process 2' }
                ],
                // Alternative: Use datapills for complex types
                // check: params.inputs.cmpx,              //  FlowObject via datapill
                // processIds: params.inputs.someArray,    //  FlowArray via datapill
            }
        )
        */

        //  For outputs, demonstrate all types work with assignSubflowOutputs
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign_all_types_outputs'],
                annotation: 'Assign outputs with various data types',
            },
            params.outputs,
            {
                test: 'Processing completed successfully', //  String literal (direct value)
            }
        )
    }
)
